    frappe.log_error("check_out_taxi_driver", str(e))
    frappe.response["message"] = {"error": str(e)}

try:
    if frappe.db.get_single_value("Security Ops Settings", "feature_supplier_badges") == 0:
        raise Exception("This feature is not enabled on this instance.")
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    name = ""
    try:
        name = str(data["name"] or "").strip()
    except (KeyError, TypeError):
        name = ""

    badge_number_raw = ""
    try:
        badge_number_raw = str(data["badge_number"]) if data["badge_number"] is not None else ""
    except (KeyError, TypeError):
        badge_number_raw = ""

    if not name:
        frappe.response["message"] = {"error": "name is required"}
    elif not badge_number_raw:
        frappe.response["message"] = {"error": "badge_number is required"}
    else:
        appt = frappe.db.get_value(
            "Appointment",
            name,
            ["name", "custom_supplier_badge", "custom_contractor_ref", "custom_company"],
            as_dict=True,
        )
        if not appt:
            frappe.response["message"] = {"error": "Appointment " + name + " not found"}
        else:
            try:
                badge_number = int(badge_number_raw)
            except Exception:
                badge_number = None

            if badge_number is None:
                frappe.response["message"] = {"error": "badge_number must be a number"}
            else:
                # Which company badge pool this is issuing from - same
                # resolution order as issue_visitor_badge.py: Employee
                # linked to this login first, then Security Guard matched
                # by full name. Falls back to the visit's own
                # custom_company (stamped at contractor check-in) when
                # neither resolves.
                current_user = frappe.session.user
                company = ""
                employee = frappe.db.get_value(
                    "Employee", {"user_id": current_user}, "company"
                )
                if employee:
                    company = employee
                else:
                    user_full = frappe.db.get_value("User", current_user, "full_name") or ""
                    if user_full:
                        guard_company = frappe.db.get_value(
                            "Security Guard", {"full_name": user_full}, "company"
                        )
                        if guard_company:
                            company = guard_company

                if not company:
                    company = appt.custom_company or ""

                if not company:
                    frappe.response["message"] = {
                        "error": "Could not determine which company badge pool to use "
                        "- no Employee or Security Guard record linked to this user, "
                        "and this visit has no custom_company fallback either"
                    }
                else:
                    badge = frappe.db.get_value(
                        "Supplier Badge",
                        {"company": company, "badge_number": badge_number},
                        ["name", "status", "current_appointment"],
                        as_dict=True,
                    )
                    if not badge:
                        frappe.response["message"] = {
                            "error": "Badge " + str(badge_number) + " does not exist for " + company
                        }
                    elif badge.status == "Issued" and badge.current_appointment != name:
                        frappe.response["message"] = {
                            "error": "Badge "
                            + str(badge_number)
                            + " ("
                            + company
                            + ") is already issued to another visit ("
                            + str(badge.current_appointment)
                            + ")"
                        }
                    else:
                        # Same physical object, reusable across many
                        # different suppliers over time (deliberately
                        # overriding this badge\'s previous "stays with one
                        # supplier long-term" design) - supplier is a
                        # snapshot of whoever currently holds it, not a
                        # permanent assignment, exactly like Visitor Badge
                        # never stores visitor identity at all.
                        #
                        # Same optimistic-concurrency protection as
                        # issue_visitor_badge.py: load + save (not a raw
                        # set_value) so two guards issuing the same
                        # badge_number in the same instant can\'t both
                        # succeed.
                        badge_doc = frappe.get_doc("Supplier Badge", badge.name)
                        badge_doc.status = "Issued"
                        badge_doc.current_appointment = name
                        badge_doc.supplier = appt.custom_contractor_ref or badge_doc.supplier
                        try:
                            badge_doc.save(ignore_permissions=True)
                        except frappe.TimestampMismatchError:
                            frappe.response["message"] = {
                                "error": "Badge "
                                + str(badge_number)
                                + " ("
                                + company
                                + ") was just issued to another visit - rescan or pick a different badge."
                            }
                        else:
                            frappe.db.set_value("Appointment", name, "custom_supplier_badge", badge.name)
                            frappe.db.commit()
                            frappe.response["message"] = {
                                "badge_number": badge_number,
                                "company": company,
                                "supplier": badge_doc.supplier or "",
                            }
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("issue_supplier_badge", str(e))
    frappe.response["message"] = {"error": str(e)}

